
export interface ProjectMetadataMigration {
  description: string;
  sql: string;
}

export const PROJECT_METADATA_MIGRATIONS: readonly ProjectMetadataMigration[] =
  [
    {
      description:
        'variant history projection: metadata_state + variants + list indexes',
      sql: `
  CREATE TABLE metadata_state (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );

  CREATE TABLE variants (
    session_id TEXT NOT NULL,
    variant_id TEXT NOT NULL,
    label TEXT NOT NULL,
    brief TEXT NOT NULL,
    session_prompt TEXT NOT NULL,
    run_label TEXT,
    status TEXT NOT NULL,
    created_at TEXT NOT NULL,
    status_changed_at TEXT NOT NULL,
    has_tree INTEGER NOT NULL,
    serve_kind TEXT,
    has_static_preview INTEGER NOT NULL,
    manifest_mtime_ms INTEGER NOT NULL,
    manifest_json TEXT NOT NULL,
    PRIMARY KEY (session_id, variant_id)
  );

  CREATE INDEX variants_created_at_idx ON variants(created_at DESC);
  CREATE INDEX variants_status_idx ON variants(status);
  `,
    },
  ];

export const PROJECT_METADATA_SCHEMA_VERSION =
  PROJECT_METADATA_MIGRATIONS.length;

export class UnsupportedSchemaVersionError extends Error {
  constructor(version: number, supportedVersion: number) {
    super(
      `ProjectMetadataStore: database uses schema version ${version}, newer than this build supports (${supportedVersion}) — leaving it untouched`,
    );
    this.name = 'UnsupportedSchemaVersionError';
  }
}

export const applyProjectMetadataMigrations = (
  db: import('node:sqlite').DatabaseSync,
  args: {
    migrations?: readonly ProjectMetadataMigration[];
    toVersion?: number;
  } = {},
): { fromVersion: number; toVersion: number } => {
  const migrations = args.migrations ?? PROJECT_METADATA_MIGRATIONS;
  const target = args.toVersion ?? migrations.length;
  const versionRow = db.prepare('PRAGMA user_version').get() as {
    user_version: number;
  };
  const fromVersion = versionRow.user_version;
  if (fromVersion > migrations.length) {
    throw new UnsupportedSchemaVersionError(fromVersion, migrations.length);
  }
  for (let applied = fromVersion; applied < target; applied++) {
    db.exec('BEGIN IMMEDIATE');
    try {
      db.exec(migrations[applied].sql);
      db.exec(`PRAGMA user_version = ${applied + 1}`);
      db.exec('COMMIT');
    } catch (err) {
      db.exec('ROLLBACK');
      throw err;
    }
  }
  return { fromVersion, toVersion: Math.max(fromVersion, target) };
};
